tape( 'the function throws an error if provided insufficient number of arguments', function test( t ) {
	var x;
	var y;

	x = zeros( [ 2, 2 ], {
		'dtype': 'generic'
	});
	y = scalar2ndarray( 0.0, {
		'dtype': 'generic'
	});

	t.throws( badValue1, TypeError, 'throws an error when provided insufficient arguments' );
	t.throws( badValue2, TypeError, 'throws an error when provided insufficient arguments' );
	t.throws( badValue3, TypeError, 'throws an error when provided insufficient arguments' );
	t.end();

	function badValue1() {
		firstIndexLessThan( x );
	}

	function badValue2() {
		firstIndexLessThan( x, y );
	}

	function badValue3() {
		firstIndexLessThan();
	}
});

tape( 'the function throws an error if provided a second argument which is not broadcast-compatible with the first argument', function test( t ) {
	var values;
	var opts;
	var out;
	var x;
	var i;

	opts = {
		'dtype': 'generic'
	};
	x = zeros( [ 2, 2 ], opts );
	out = zeros( [], opts );

	values = [
		zeros( [ 4 ], opts ),
		zeros( [ 2, 2, 2 ], opts ),
		zeros( [ 0 ], opts )
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			firstIndexLessThan( x, value, out );
		};
	}
});

